        ena = 0;
        amount = 2'b00;
        data = 64'd0;

        @(posedge clk);
        #1;

        // Test 1: Synchronous Load
        load = 1;
        ena = 0;
        data = 64'h8000_0000_0000_0005; // MSB is 1 for arithmetic shift testing
        @(posedge clk);
        #1;
        expected_q = 64'h8000_0000_0000_0005;
        if (q !== expected_q) begin
            errors = errors + 1;
            $display("ERROR: Load failed. Expected: %h, Got: %h", expected_q, q);
