        load = 0;
        ena = 0;
        amount = 2'b00;
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            errors = errors + 1;
            $display("ERROR: Hold failed when ena=0. Expected: %h, Got: %h", expected_q, q);
        end

        // Test 3: Shift left by 1 (amount = 2'b00)
        load = 0;
        ena = 1;
        amount = 2'b00;
        // Current expected_q = 8000_0000_0000_0005
        // Shift left by 1 -> 0000_0000_0000_000A (ignoring overflow, LSB gets 0)
        expected_q = {expected_q[62:0], 1'b0};
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            errors = errors + 1;
            $display("ERROR: Shift left by 1 failed. Expected: %h, Got: %h", expected_q, q);
        end

        // Test 4: Shift left by 8 (amount = 2'b01)
        load = 0;
        ena = 1;
        amount = 2'b01;
        expected_q = {expected_q[55:0], 8'h00};
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            errors = errors + 1;
            $display("ERROR: Shift left by 8 failed. Expected: %h, Got: %h", expected_q, q);
        end

        // Test 5: Load a known pattern with MSB = 1 for arithmetic right shift
        load = 1;
        ena = 0;
        data = 64'hF000_0000_0000_00FF;
        @(posedge clk);
        #1;
        expected_q = 64'hF000_0000_0000_00FF;

        // Test 6: Shift right by 1, arithmetic (amount = 2'b10)
        load = 0;
        ena = 1;
        amount = 2'b10;
        // Arithmetic shift right: sign extension
        expected_q = {expected_q[63], expected_q[63:1]};
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            errors = errors + 1;
            $display("ERROR: Shift right by 1 (arithmetic) failed. Expected: %h, Got: %h", expected_q, q);
        end

        // Test 7: Shift right by 8, arithmetic (amount = 2'b11)
        load = 0;
        ena = 1;
        amount = 2'b11;
        expected_q = {{8{expected_q[63]}}, expected_q[63:8]};
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            errors = errors + 1;
            $display("ERROR: Shift right by 8 (arithmetic) failed. Expected: %h, Got: %h", expected_q, q);
        end

        // Test 8: Positive number arithmetic right shift (MSB = 0)
        load = 1;
        ena = 0;
        data = 64'h0F00_0000_0000_00FF;
        @(posedge clk);
        #1;
        expected_q = 64'h0F00_0000_0000_00FF;

        load = 0;
        ena = 1;
        amount = 2'b10; // Shift right by 1
        expected_q = {1'b0, expected_q[63:1]};
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            errors = errors + 1;
            $display("ERROR: Shift right by 1 (positive sign extension) failed. Expected: %h, Got: %h", expected_q, q);
        end

        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule
